27	#[inline]
28	pub(crate) fn parse_percentage_dimension(p: &mut CssParser) -> ParsedSyntax {
29	    if !is_at_percentage_dimension(p) {
30	        return Absent;
31	    }
32	
33	    let m = p.start();
34	    // Re-cast the value portion of the dimension as a number literal.
35	    p.bump_remap(CSS_NUMBER_LITERAL);
36	    // CSS_PERCENTAGE_VALUE guarantees the `%` will be the next token,
37	    // but we can use expect just to be safe.
38	    p.expect(T![%]);
39	    Present(m.complete(p, CSS_PERCENTAGE))
40	}
