47	#[inline]
48	pub(crate) fn parse_regular_dimension(p: &mut CssParser) -> ParsedSyntax {
49	    if !is_at_regular_dimension(p) {
50	        return Absent;
51	    }
52	
53	    let m = p.start();
54	    // Re-cast the value portion of the dimension as a number literal.
55	    p.bump_remap(CSS_NUMBER_LITERAL);
56	
57	    // Any identifier is valid as a dimension unit, but for known units we
58	    // use `CssRegularDimension` as a convenience elsewhere to know that the
59	    // unit is valid. All other identifiers become `CssUnknownDimension`.
60	    let kind = if is_nth_at_unit(p, 0) {
61	        CSS_REGULAR_DIMENSION
62	    } else {
63	        CSS_UNKNOWN_DIMENSION
64	    };
65	
66	    // CSS_DIMENSION_VALUE guarantees that an identifier will follow the
67	    // number parsed previously, but the lexer will most likely treat it
68	    // as a keyword (like `px` as PX_KW), so it needs to be re-cast to just
69	    // an ident.
70	    p.bump_remap(T![ident]);
71	
72	    Present(m.complete(p, kind))
73	}
